contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint minSum, address logAddr) public payable {
        c.SetMinSum(minSum); if (__ESBMC_reverted()) return;
        c.Initialized(); if (__ESBMC_reverted()) return;

        uint minSumBefore = c.MinSum(); if (__ESBMC_reverted()) return;
        uint balanceBefore = address(c).balance;

        bool reverted;
        c.SetLogFile(logAddr); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(reverted || (c.MinSum() == minSumBefore && address(c).balance == balanceBefore));
    }

    receive() external payable {}
}

